import { addDays, addMonths, daysBetween } from './dates.js';

/** Billing cycles a plan can have. */
export const CYCLE = Object.freeze({ WEEK: 'weekly', MONTH: 'monthly', YEAR: 'yearly' });

/** Every supported cycle, as stored in the subscriptions file. */
export const CYCLES = Object.freeze(Object.values(CYCLE));

const MONTHS_PER_CHARGE = { [CYCLE.MONTH]: 1, [CYCLE.YEAR]: 12 };

// a month's share of one charge, as [numerator, denominator]
const MONTHLY_SHARE = { [CYCLE.WEEK]: [52, 12], [CYCLE.MONTH]: [1, 1], [CYCLE.YEAR]: [1, 12] };

/**
 * What a plan costs per month as an exact fraction of cents: [numerator, denominator].
 * @param {{ price: number, cycle: string }} sub
 * @returns {[number, number]}
 */
export function monthlyExact(sub) {
  const [n, d] = MONTHLY_SHARE[sub.cycle];
  return [sub.price * n, d];
}

/**
 * Round a fraction of cents to the nearest whole cent (halves go up).
 * @param {number} num
 * @param {number} den
 * @returns {number}
 */
export function roundCents(num, den) {
  return Math.floor((2 * num + den) / (2 * den));
}

/**
 * What a plan costs per month, in whole cents (rounded to the nearest cent).
 * @param {{ price: number, cycle: string }} sub
 * @returns {number}
 */
export function monthlyCents(sub) {
  return roundCents(...monthlyExact(sub));
}

/**
 * The date of a plan's next charge on or after `today` ('YYYY-MM-DD').
 * Monthly and yearly charges fall on the day of the month of the first charge (`since`), or the last day of a shorter month.
 * Weekly charges fall every 7 days from `since`.
 * @param {{ cycle: string, since: string }} sub
 * @param {string} today
 * @returns {string}
 */
export function nextCharge(sub, today) {
  if (sub.cycle === CYCLE.WEEK) {
    if (sub.since >= today) return sub.since;
    return addDays(sub.since, Math.ceil(daysBetween(sub.since, today) / 7) * 7);
  }
  const step = MONTHS_PER_CHARGE[sub.cycle];
  let n = 0;
  let date = sub.since;
  while (date < today) {
    n += 1;
    date = addMonths(sub.since, n * step);
  }
  return date;
}

